%%\ 
% **this program plots a 1st ODE system
% where the system approaches a steady-state
% value in accordance to parameters**
% 
% 
% This is the order of inputs:
% 
% *u* is desired speed
% *x* is current speed
% *tau* is time constant
% *dt* is delta time
% *time_end* is the upper bound of time range
%   time_end is 5 * tau so that the simulation
%   will end around a 99.3% of the change from the initial value
%   to the final value
%   note: the only applies to first order ODEs like this one



%motion entry calls
u = 5; x = -10; tau = 0.1; dt = 0.01; time_end = 5 * tau;
[y1, t1] = simulateFirstOrderSpeed(u, x, tau, dt, time_end);

u = 5; x = -10; tau = 0.5; dt = 0.01; time_end = 5 * tau;
[y2, t2] = simulateFirstOrderSpeed(u, x, tau, dt, time_end);

u = 5; x = -10; tau = 1; dt = 0.01; time_end = 5 * tau;
[y3, t3] = simulateFirstOrderSpeed(u, x, tau, dt, time_end);

%plotting the motion entries over time
hold on %[output:78559a57]
plot(t1, y1, "r", LineWidth=3) %[output:78559a57]
plot(t2, y2, "g", LineWidth=3) %[output:78559a57]
plot(t3, y3, "b", LineWidth=3) %[output:78559a57]

title("") %[output:78559a57]
ylabel("speed (m/s)"); %[output:78559a57]
xlabel("time (s)") %[output:78559a57]

